import{_ as a,o,c as t,a3 as s}from"./chunks/framework.DMtjdCb-.js";const i="/help/assets/fnos-compose.BtztsxpA.png",k=JSON.parse('{"title":"2. NAS 联合部署","description":"","frontmatter":{},"headers":[],"relativePath":"zh-Hans/docker.md","filePath":"zh-Hans/docker.md"}'),n={name:"zh-Hans/docker.md"};function r(d,e,l,c,h,p){return o(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="_2-nas-联合部署" tabindex="-1">2. NAS 联合部署 <a class="header-anchor" href="#_2-nas-联合部署" aria-label="Permalink to &quot;2. NAS 联合部署&quot;">​</a></h1><p>默认组合一次部署四个服务：AnimeMachine 提供操作页面，Ani-RSS 负责订阅，qBittorrent 下载媒体，Torrent Collector 提供 Torrent 检索。首次启动自动建立连接和账户，后续在 AnimeMachine 中操作即可。</p><h2 id="准备项目目录" tabindex="-1">准备项目目录 <a class="header-anchor" href="#准备项目目录" aria-label="Permalink to &quot;准备项目目录&quot;">​</a></h2><ol><li>在 NAS 的应用中心安装并打开 <strong>Docker / 容器管理</strong>。终端部署使用 Docker Engine 24+、Compose 2.20.3+。</li><li>在 NAS 的数据盘上新建固定目录，例如 <code>docker/animemachine</code>，并确认有足够的可用空间。</li><li><a href="/help/downloads/compose.yaml" download="compose.yaml">下载 compose.yaml</a>，保存到这个目录。在 GitHub 文件页面可点击 <strong>Download raw file</strong>。保存后的完整文件名为 <strong><code>compose.yaml</code></strong>。</li></ol><p>默认会在项目目录内建立 <code>config</code>、<code>data</code>、<code>library</code>、<code>torrents</code> 和 <code>external</code> 等目录。下载的动画存放在 <code>library</code> 或 <code>external/ani-rss</code>；因此应把项目建在有足够空间的磁盘上。</p><h2 id="飞牛等-nas-的图形化部署" tabindex="-1">飞牛等 NAS 的图形化部署 <a class="header-anchor" href="#飞牛等-nas-的图形化部署" aria-label="Permalink to &quot;飞牛等 NAS 的图形化部署&quot;">​</a></h2><ol><li>在 Docker 应用中进入 <strong>Compose / 项目</strong>，创建名为 <code>animemachine</code> 的项目。</li><li>项目路径选择刚才新建的目录。</li><li>导入 <code>compose.yaml</code>，或打开该文件，将全部内容粘贴到项目编辑器。</li><li>启动项目，等待镜像下载与容器启动。</li></ol><p>界面名称可能随 NAS 系统版本变化；需要指定的始终是<strong>项目名称、项目路径和同一个 Compose 文件</strong>。</p><h2 id="使用终端部署" tabindex="-1">使用终端部署 <a class="header-anchor" href="#使用终端部署" aria-label="Permalink to &quot;使用终端部署&quot;">​</a></h2><p>已在项目目录打开终端时，运行：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p>查看状态：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ps</span></span></code></pre></div><p><strong>完成标志：</strong> 四个服务处于运行状态。Ani-RSS 和采集器会等待 AnimeMachine 启动就绪；首次拉取镜像时，项目页面会持续显示下载进度。</p><h2 id="打开页面并获取密码" tabindex="-1">打开页面并获取密码 <a class="header-anchor" href="#打开页面并获取密码" aria-label="Permalink to &quot;打开页面并获取密码&quot;">​</a></h2><ol><li>在电脑浏览器打开 <strong><code>http://NAS地址:8787</code></strong>，例如 <code>http://192.168.1.20:8787</code>。</li><li>在容器管理页面选择 <strong>animemachine → 日志</strong>，找到首次登录用户名和随机密码。</li><li>用该账户登录，继续<a href="./first-use.html">首次打开</a>。</li></ol><p>终端中可使用：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> animemachine</span></span></code></pre></div><table tabindex="0"><thead><tr><th>页面</th><th>局域网地址</th></tr></thead><tbody><tr><td>AnimeMachine</td><td><code>http://NAS地址:8787</code></td></tr><tr><td>Ani-RSS</td><td><code>http://NAS地址:7789</code></td></tr><tr><td>qBittorrent</td><td><code>http://NAS地址:8080</code></td></tr></tbody></table><p>日常使用 AnimeMachine 即可。若要打开后两个管理页面，用户名为 <code>admin</code>；初始密码分别保存在项目目录的 <code>config/ani-rss/.animemachine/web-password</code>、<code>config/qbittorrent/.animemachine/web-password</code>。</p><h2 id="已有下载服务或指定媒体目录" tabindex="-1">已有下载服务或指定媒体目录 <a class="header-anchor" href="#已有下载服务或指定媒体目录" aria-label="Permalink to &quot;已有下载服务或指定媒体目录&quot;">​</a></h2><p>已有 Ani-RSS / qBittorrent 时，可改用 <a href="https://github.com/kyupi-git/animemachine/tree/main/deploy/compose/templates" target="_blank" rel="noreferrer">01 或 02 模板</a>，再在 <strong>设置 → 连接</strong> 中填写已有服务地址。默认文件与模板是替代方案，选一个部署即可。</p><p>需要使用其它磁盘目录时，按<a href="./collections.html#docker-folders">已有收藏</a>设置目录映射。完整组合会自动检查公开资源来源的连接情况，并在需要时选择可用备用来源。</p><h2 id="本步常见问题" tabindex="-1">本步常见问题 <a class="header-anchor" href="#本步常见问题" aria-label="Permalink to &quot;本步常见问题&quot;">​</a></h2><ul><li><strong>显示“找不到配置文件”：</strong> 在保存 <code>compose.yaml</code> 的目录运行命令，并核对文件没有被保存为 <code>compose.yaml.txt</code>。</li><li><strong>镜像下载失败：</strong> 查看 NAS Docker 的具体错误，恢复下载后再次执行同一启动命令，已下载的层会继续使用。</li><li><strong>端口已被占用：</strong> 在同目录 <code>.env</code> 中设置空闲端口，如 <code>ANM_WEB_PORT=8788</code>，再运行 <code>docker compose up -d</code>，访问地址也改用 8788。</li><li><strong>只想暂停使用：</strong> 在项目页面停止项目，或运行 <code>docker compose stop</code>。配置、记录和媒体仍保存在项目目录。</li></ul><p>如果镜像仓库连接失败，且已有可用的 HTTP 代理，可在飞牛 <strong>Docker → 设置 → 代理设置</strong> 中填写自己的代理地址，再重试部署。这一设置用于拉取镜像；网络可正常访问镜像仓库时，可保持关闭。</p><p><img src="'+i+'" alt="飞牛 Docker 代理设置：填写实际可用的 HTTP 代理地址" loading="lazy"></p>',27)])])}const g=a(n,[["render",r]]);export{k as __pageData,g as default};
